import{d as u,C as t,o as h,c as y,j as a,a as n,E as l,a3 as s}from"./chunks/framework.Q4yG9rk_.js";const p=JSON.parse('{"title":"序卦传","description":"讲六十四卦次序之理的传——从天地万物、夫妇人伦到既济未济，读懂卦与卦之间为什么这样相承。","frontmatter":{"title":"序卦传","description":"讲六十四卦次序之理的传——从天地万物、夫妇人伦到既济未济，读懂卦与卦之间为什么这样相承。","category":"guide","aliases":["序卦传","序卦","xu gua zhuan"],"source":["《周易·序卦传》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/shi-yi/xu-gua-zhuan.md","filePath":"yijing/shi-yi/xu-gua-zhuan.md","lastUpdated":1790587309000}'),x={name:"yijing/shi-yi/xu-gua-zhuan.md"},w=u({...x,setup(c){const i=[{id:"duan-01",label:"一、天地生万物",showLabel:!0,sentences:[["有天地，然后万物生焉。盈天地之间者唯万物，故",{text:"受之以",glossary:"g02"},"《",{text:"屯",glossary:"g03"},"》。"]],note:["有了天地，才有万物；而充塞天地之间的也只是万物，所以接下来是屯卦——屯，就是万物初生、生机已具而尚未舒展的样子。"]},{id:"duan-02",label:"二、屯者物始生",showLabel:!0,sentences:[["屯者，盈也。屯者，物之始生也。物生必",{text:"蒙",glossary:"g04"},"，故",{text:"受之以",glossary:"g02"},"《蒙》。"]],note:["屯是充盈，也是万物刚刚开始生长；初生之物必然蒙昧，所以接下来是蒙卦。"]},{id:"duan-03",label:"三、蒙者物之稚",showLabel:!0,sentences:[["蒙者，蒙也，物之稚也。物稚不可不养也，故",{text:"受之以",glossary:"g02"},"《需》。"]],note:["蒙是幼稚；幼稚的东西不能不养育，所以接下来是需卦。"]},{id:"duan-04",label:"四、需讼师相因",showLabel:!0,sentences:[["需者，饮食之道也。饮食必有讼，故",{text:"受之以",glossary:"g02"},"《讼》。讼必有众起，故",{text:"受之以",glossary:"g02"},"《师》。"]],note:["需讲的是饮食之道；饮食上有了争执，就成了讼卦；争讼多了必要有众人来裁断，于是有了师卦。"]},{id:"duan-05",label:"五、比小畜",showLabel:!0,sentences:[["师者，众也。众必有所比，故",{text:"受之以",glossary:"g02"},"《比》。比者，比也。比必有所畜，故",{text:"受之以",glossary:"g02"},"《小畜》。"]],note:["师是众人；众人必然有所亲比，所以接下来是比卦；亲比相合就会有所积蓄，所以接下来是小畜卦。"]},{id:"duan-06",label:"六、履泰",showLabel:!0,sentences:[["物畜然后有礼，故",{text:"受之以",glossary:"g02"},"《",{text:"履",glossary:"g05"},"》。履而",{text:"泰",glossary:"g06"},"，然后安，故",{text:"受之以",glossary:"g02"},"《泰》。泰者，通也。"]],note:["物有所积蓄之后，就要有礼来分其节，所以接下来是履卦；依礼而行而得通泰，然后才安稳，所以接下来是泰卦。"]},{id:"duan-07",label:"七、否同人大有",showLabel:!0,sentences:[["物不可以终通，故",{text:"受之以",glossary:"g02"},"《",{text:"否",glossary:"g07"},"》。物不可以终否，故",{text:"受之以",glossary:"g02"},"《同人》。与人同者，物必归焉，故",{text:"受之以",glossary:"g02"},"《大有》。"]],note:["事物不可能永远通泰，所以接下来是否卦；也不可能永远闭塞，所以接下来是同人卦——与人和同，众物自然来归附，所以接下来是大有卦。"]},{id:"duan-08",label:"八、谦豫随蛊",showLabel:!0,sentences:[["有大者，不可以盈，故",{text:"受之以",glossary:"g02"},"《谦》。有大而能谦必豫，故",{text:"受之以",glossary:"g02"},"《豫》。豫必有随，故",{text:"受之以",glossary:"g02"},"《随》。以喜随人者必有事，故",{text:"受之以",glossary:"g02"},"《",{text:"蛊",glossary:"g08"},"》。"]],note:["拥有盛大不可自满，所以接下来是谦卦；盛大而能谦，必能得欢愉，所以接下来是豫卦；欢愉就有人相随，所以接下来是随卦；而一味以喜悦随人、失了觉察，就必生事端，所以接下来是蛊卦。"]},{id:"duan-09",label:"九、临观",showLabel:!0,sentences:[["蛊者，事也。有事而后可大，故",{text:"受之以",glossary:"g02"},"《临》。临者，大也。物大然后可观，故",{text:"受之以",glossary:"g02"},"《观》。"]],note:["蛊是事端、也是整治之事；有事可为之后才能盛大，所以接下来是临卦；盛大之后便可观仰，所以接下来是观卦。"]},{id:"duan-10",label:"十、噬嗑贲",showLabel:!0,sentences:[["可观而后有所合，故",{text:"受之以",glossary:"g02"},"《噬嗑》。嗑者，合也。物不可以苟合而已，故",{text:"受之以",glossary:"g02"},"《贲》。"]],note:["可观之后便有所聚合，所以接下来是噬嗑卦；但相合不能苟且，所以接下来是贲卦——贲是文饰，使相合者有序有文。"]},{id:"duan-11",label:"十一、贲极而剥",showLabel:!0,sentences:[["贲者，饰也。致饰然后亨则尽矣，故",{text:"受之以",glossary:"g02"},"《剥》。剥者，剥也。"]],note:["贲是文饰；文饰到了极点，通达也就到了尽头，所以接下来是剥卦。"]},{id:"duan-12",label:"十二、复无妄",showLabel:!0,sentences:[["物不可以终尽剥，穷上反下，故",{text:"受之以",glossary:"g02"},"《复》。复则不妄矣，故",{text:"受之以",glossary:"g02"},"《无妄》。"]],note:["事物不可能一直剥落殆尽：穷于上便返于下，所以接下来是复卦；能复归根本便不妄为，所以接下来是无妄卦。"]},{id:"duan-13",label:"十三、大畜颐",showLabel:!0,sentences:[["有无妄，物然后可畜，故",{text:"受之以",glossary:"g02"},"《大畜》。物畜然后可养，故",{text:"受之以",glossary:"g02"},"《颐》。颐者，养也。"]],note:["有了无妄之实，物才可以蓄积，所以接下来是大畜卦；物既蓄积才可以养，所以接下来是颐卦。"]},{id:"duan-14",label:"十四、大过坎离",showLabel:!0,sentences:[["不养则不可动，故",{text:"受之以",glossary:"g02"},"《大过》。物不可以终过，故",{text:"受之以",glossary:"g02"},"《坎》。坎者，陷也。陷必有所丽，故",{text:"受之以",glossary:"g02"},"《离》。离者，丽也。"]],note:["不养就不能动，所以接下来是大过卦；但物不可以长久过甚，所以接下来是坎卦；陷落之后必有所依附，所以接下来是离卦。"]},{id:"duan-15",label:"十五、人伦之序",showLabel:!0,sentences:[["有天地然后有万物，有万物然后有男女，有男女然后有夫妇，有夫妇然后有父子，有父子然后有君臣，有君臣然后有上下，有上下然后礼义有所错。"]],note:["有了天地才有万物，有了万物才有男女，有了男女才有夫妇，有了夫妇才有父子，有了父子才有君臣，有了君臣才有上下，有了上下礼义才有所安放。"]},{id:"duan-16",label:"十六、恒遁",showLabel:!0,sentences:[["夫妇之道不可以不久也，故",{text:"受之以",glossary:"g02"},"《恒》。恒者，久也。物不可以久居其所，故",{text:"受之以",glossary:"g02"},"《遁》。遁者，退也。"]],note:["夫妇之道不可以不长久，所以接下来是恒卦；但事物又不可以长久停在一处，所以接下来是遁卦——遁是退避。"]},{id:"duan-17",label:"十七、壮晋明夷",showLabel:!0,sentences:[["物不可以终遁，故",{text:"受之以",glossary:"g02"},"《大壮》。物不可以终壮，故",{text:"受之以",glossary:"g02"},"《晋》。晋者，进也。进必有所伤，故",{text:"受之以",glossary:"g02"},"《明夷》。"]],note:["事物不可一直退避，所以接下来是大壮卦；也不可一直壮盛，所以接下来是晋卦——晋是前进；而前进必有所伤，所以接下来是明夷卦。"]},{id:"duan-18",label:"十八、家人睽",showLabel:!0,sentences:[["夷者，伤也。伤于外者必反于家，故",{text:"受之以",glossary:"g02"},"《家人》。家道穷必乖，故",{text:"受之以",glossary:"g02"},"《睽》。睽者，乖也。"]],note:["明夷是受伤；在外受伤必返归于家，所以接下来是家人卦；而家道穷困必致乖离，所以接下来是睽卦。"]},{id:"duan-19",label:"十九、蹇解",showLabel:!0,sentences:[["乖必有难，故",{text:"受之以",glossary:"g02"},"《蹇》。蹇者，难也。物不可以终难，故",{text:"受之以",glossary:"g02"},"《解》。解者，缓也。"]],note:["乖离必有艰难，所以接下来是蹇卦；但事物不可长久困于难，所以接下来是解卦——解是舒缓。"]},{id:"duan-20",label:"二十、损益夬",showLabel:!0,sentences:[["缓必有所失，故",{text:"受之以",glossary:"g02"},"《损》。损而不已必益，故",{text:"受之以",glossary:"g02"},"《益》。益而不已必决，故",{text:"受之以",glossary:"g02"},"《夬》。夬者，决也。"]],note:["舒缓必有所失，所以接下来是损卦；损到不能再减时必转为益，所以接下来是益卦；益到不能再增时必致决裂，所以接下来是夬卦。"]},{id:"duan-21",label:"二十一、姤萃升",showLabel:!0,sentences:[["决必有遇，故",{text:"受之以",glossary:"g02"},"《姤》。姤者，遇也。物相遇而后聚，故",{text:"受之以",glossary:"g02"},"《萃》。萃者，聚也。"]],note:["决裂之后必有相遇，所以接下来是姤卦；相遇而后相聚，所以接下来是萃卦；聚而向上就叫做升卦。"]},{id:"duan-22",label:"二十二、困井",showLabel:!0,sentences:[["聚而上者谓之升，故",{text:"受之以",glossary:"g02"},"《升》。升而不已必困，故",{text:"受之以",glossary:"g02"},"《困》。困乎上者必反下，故",{text:"受之以",glossary:"g02"},"《井》。"]],note:["升而不止必致困顿，所以接下来是困卦；困于上者必返于下，所以接下来是井卦——回到基础与持续的供养。"]},{id:"duan-23",label:"二十三、革鼎震",showLabel:!0,sentences:[["井道不可不革，故",{text:"受之以",glossary:"g02"},"《革》。革物者莫若鼎，故",{text:"受之以",glossary:"g02"},"《鼎》。主器者莫若长子，故",{text:"受之以",glossary:"g02"},"《震》。震者，动也。"]],note:["井道久而不变就须革，所以接下来是革卦；变革事物没有比鼎更有效的，所以接下来是鼎卦；主掌祭器没有比长子更合宜的，所以接下来是震卦。"]},{id:"duan-24",label:"二十四、艮渐",showLabel:!0,sentences:[["物不可以终动，止之，故",{text:"受之以",glossary:"g02"},"《艮》。艮者，止也。物不可以终止，故",{text:"受之以",glossary:"g02"},"《渐》。渐者，进也。"]],note:["事物不可一直动，要有所止，所以接下来是艮卦；也不可一直止，所以接下来是渐卦——渐是渐进。"]},{id:"duan-25",label:"二十五、归妹丰旅",showLabel:!0,sentences:[["进必有所归，故",{text:"受之以",glossary:"g02"},"《归妹》。得其所归者必大，故",{text:"受之以",glossary:"g02"},"《丰》。丰者，大也。穷大者必失其居，故",{text:"受之以",glossary:"g02"},"《旅》。"]],note:["渐进必有所归宿，所以接下来是归妹卦；得其所归必盛大，所以接下来是丰卦；而盛大至极必失其居，所以接下来是旅卦。"]},{id:"duan-26",label:"二十六、巽兑",showLabel:!0,sentences:[["旅而无所容，故",{text:"受之以",glossary:"g02"},"《巽》。巽者，入也。入而后说之，故",{text:"受之以",glossary:"g02"},"《兑》。兑者，说也。"]],note:["旅居而无所容身，所以接下来是巽卦——巽是入；入而后能相悦，所以接下来是兑卦。"]},{id:"duan-27",label:"二十七、涣节",showLabel:!0,sentences:[["说而后散之，故",{text:"受之以",glossary:"g02"},"《涣》。涣者，离也。物不可以终离，故",{text:"受之以",glossary:"g02"},"《节》。"]],note:["相悦而后会涣散，所以接下来是涣卦；但物不可长久离散，所以接下来是节卦——节是节制。"]},{id:"duan-28",label:"二十八、孚过既济",showLabel:!0,sentences:[["节而信之，故",{text:"受之以",glossary:"g02"},"《中孚》。有其信者必行之，故",{text:"受之以",glossary:"g02"},"《小过》。有过物者必济，故",{text:"受之以",glossary:"g02"},"《",{text:"既济",glossary:"g11"},"》。"]],note:["有所节制而后能取信于人，所以接下来是中孚卦；有信必见于行动，所以接下来是小过卦；能过越常分者必能度过，所以接下来是既济卦。"]},{id:"duan-29",label:"二十九、未济终篇",showLabel:!0,sentences:[["物不可穷也，故",{text:"受之以",glossary:"g02"},"《",{text:"未济",glossary:"g12"},"》，终焉。"]],note:["万物不可以穷尽，所以接下来是未济卦，全篇到此结束。"]}],o=[{id:"g01",term:"序卦",pinyin:"xù guà",meaning:"说明六十四卦次序与相承理由的《易传》篇名。它关注卦与卦之间的关系，不是逐卦详解。"},{id:"g02",term:"受之以",pinyin:"shòu zhī yǐ",meaning:"承接、接续于某卦。每一个「故受之以」都在回答：前一状态为什么会带出后一状态。"},{id:"g03",term:"屯",pinyin:"zhūn",meaning:"聚集、艰难，也指万物初生而未舒展的状态。新生之物有生机，也有条件未备的纠结。"},{id:"g04",term:"蒙",pinyin:"méng",meaning:"蒙昧、幼稚。物初生而未明，需要养育、学习与引导；蒙不是终点，而是进入学习的起点。"},{id:"g05",term:"履",pinyin:"lǚ",meaning:"践履、行走，也含有依礼而行、守分知止的意味。物畜之后不能只凭力量，还需要分寸。"},{id:"g06",term:"泰",pinyin:"tài",meaning:"通达、通泰。序卦强调「物不可以终通」，提醒顺境不能被当成永恒状态。"},{id:"g07",term:"否",pinyin:"pǐ",meaning:"闭塞、不通。否并非终局，序卦接着以同人说明闭塞中仍会重新产生共同与连接。"},{id:"g08",term:"蛊",pinyin:"gǔ",meaning:"积弊、败坏之事，也包含整治积弊的任务。随喜而失察，久而久之便可能生蛊。"},{id:"g09",term:"剥复",pinyin:"bō fù",meaning:"剥是剥落，复是返回、复生。剥极不能终尽，穷上反下而复，构成《易》重要的转化节律。"},{id:"g10",term:"咸恒",pinyin:"xián héng",meaning:"咸为感应，恒为长久。下经由夫妇之道开端，写人与人如何感通并在关系中求久。"},{id:"g11",term:"既济",pinyin:"jì jì",meaning:"事情已经渡过、已经完成的状态。它虽成而未必永固，因此下一卦仍是未济。"},{id:"g12",term:"未济",pinyin:"wèi jì",meaning:"尚未渡过、尚未完成。它不是单纯失败，而是保留变化和继续行动的开放结尾。"}];return(b,e)=>{const r=t("DaoReadingPrelude"),g=t("DaoTextReading"),d=t("DaoKeywordCards");return h(),y("div",null,[e[0]||(e[0]=a("h1",{id:"序卦传",tabindex:"-1"},[n("序卦传 "),a("a",{class:"header-anchor",href:"#序卦传","aria-label":'Permalink to "序卦传"'},"​")],-1)),l(r,{title:"顺着卦与卦之间的理由读",summary:"《序卦传》篇幅不长，却回答了一个重要问题：六十四卦为什么要这样排列？它用「故受之以」把相邻卦连接起来，从天地、万物、资源、冲突与秩序，写到家庭、进退、聚散、动止、诚信，最后落在既济而未济。读它，不是背一串编号，而是看见局面如何生出下一局面。",points:[{label:"先看连接",text:"留意每个「故受之以」：它说明上一种状态为什么会引出下一种状态。"},{label:"再看转折",text:"通会转否，盛会转剥，困会求解；没有一种局面可以永远停留。"},{label:"最后回到人",text:"上经从天地万物展开，下经转入夫妇、家庭、社会与人的进退。"}],hint:"《序卦》提供的是一幅变化地图，不是要求现实必须按六十四步机械运行的剧本。先读它的因果意识，再回到具体卦义。"}),e[1]||(e[1]=s("",12)),l(g,{colophon:"天地生物 · 通塞相因 · 人伦展开 · 既济未济",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"序卦传原文",sections:i,glossary:o}),e[2]||(e[2]=a("blockquote",null,[a("p",null,"注：本页按你提供的通行本文字整理。不同底本在「遁／遁」「无／無」「错／措」「说／悦」等字形、用字和句读上可能有差异，阅读时请以所据版本为准。")],-1)),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[n("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),l(d,{items:[{term:"序卦",pinyin:["xù","guà"],meaning:"说明六十四卦次序与相承理由的《易传》篇名。它关注卦与卦之间的关系，不是逐卦详解。"},{term:"受之以",pinyin:["shòu","zhī","yǐ"],meaning:"承接、接续于某卦。每一个「故受之以」都在回答：前一状态为什么会带出后一状态。"},{term:"屯",pinyin:["zhūn"],meaning:"聚集、艰难，也指万物初生而未舒展的状态。新生之物有生机，也有条件未备的纠结。"},{term:"蒙",pinyin:["méng"],meaning:"蒙昧、幼稚。物初生而未明，需要养育、学习与引导；蒙不是终点，而是进入学习的起点。"},{term:"履",pinyin:["lǚ"],meaning:"践履、行走，也含有依礼而行、守分知止的意味。物畜之后不能只凭力量，还需要分寸。"},{term:"泰",pinyin:["tài"],meaning:"通达、通泰。序卦强调「物不可以终通」，提醒顺境不能被当成永恒状态。"},{term:"否",pinyin:["pǐ"],meaning:"闭塞、不通。否并非终局，序卦接着以同人说明闭塞中仍会重新产生共同与连接。"},{term:"蛊",pinyin:["gǔ"],meaning:"积弊、败坏之事，也包含整治积弊的任务。随喜而失察，久而久之便可能生蛊。"},{term:"剥复",pinyin:["bō","fù"],meaning:"剥是剥落，复是返回、复生。剥极不能终尽，穷上反下而复，构成《易》重要的转化节律。"},{term:"咸恒",pinyin:["xián","héng"],meaning:"咸为感应，恒为长久。下经由夫妇之道开端，写人与人如何感通并在关系中求久。"},{term:"既济",pinyin:["jì","jì"],meaning:"事情已经渡过、已经完成的状态。它虽成而未必永固，因此下一卦仍是未济。"},{term:"未济",pinyin:["wèi","jì"],meaning:"尚未渡过、尚未完成。它不是单纯失败，而是保留变化和继续行动的开放结尾。"}]}),e[4]||(e[4]=s("",21))])}}});export{p as __pageData,w as default};
